  /* Water and sewer billing policy */
  ex_bl_title: ['Water and sewer billing policy', 'Política de facturación de agua y alcantarillado'],
  ex_bl_eyebrow: ['Water and sewer', 'Agua y alcantarillado'],
  ex_bl_lead: ['Due dates, late charges, deposits, cutoff and reconnection, in plain words. Every figure here comes from the town’s own Water and Sewer Policy and Chapter 10 of the Town Code.', 'Fechas de pago, recargos, depósitos, corte y reconexión, en palabras sencillas. Cada cifra viene de la Política de Agua y Alcantarillado del pueblo y del Capítulo 10 del Código Municipal.'],
  ex_bl_when_h: ['When the bill is due', 'Cuándo se paga la factura'],
  ex_bl_when_p1: ['The town bills water and sewer once a month, by the gallons on your meter. If your sewer connection has no meter, you pay the standard sewer charge.', 'El pueblo factura agua y alcantarillado una vez al mes, según los galones que marca su medidor. Si su conexión de alcantarillado no tiene medidor, paga la tarifa estándar.'],
  ex_bl_when_p2: ['Every bill is due when you receive it. If it is not paid by the 15th of the month, a 10 percent penalty is added.', 'Cada factura se paga al recibirla. Si no se paga antes del día 15 del mes, se agrega un recargo del 10 por ciento.'],
  ex_bl_due: ['Due', 'Vence'],
  ex_bl_due_v: ['On receipt', 'Al recibirla'],
  ex_bl_late: ['Late after', 'Recargo después del'],
  ex_bl_late_v: ['The 15th of the month', 'Día 15 del mes'],
  ex_bl_penalty: ['Penalty', 'Recargo'],
  ex_bl_penalty_v: ['10% of the bill', '10% de la factura'],
  ex_bl_restore: ['To turn water back on', 'Para reconectar el agua'],
  ex_bl_restore_v: ['Past-due balance in full, plus $35.00', 'Saldo vencido completo, más $35.00'],
  ex_bl_cut_h: ['Cutoff for nonpayment', 'Corte por falta de pago'],
  ex_bl_cut_p1: ['If a bill stays unpaid, the town disconnects water service for nonpayment, following the notice rules in the Code of Virginia. Service comes back only after the whole past-due amount is paid, plus the $35.00 restoration fee.', 'Si una factura sigue sin pagarse, el pueblo desconecta el servicio de agua por falta de pago, siguiendo las reglas de aviso del Código de Virginia. El servicio vuelve solo después de pagar todo el saldo vencido, más la tarifa de reconexión de $35.00.'],
  ex_bl_cut_p2: ['A complaint about a bill does not excuse paying it on time (Town Code § 10-4). If you think a reading is wrong, pay the bill and ask Billing to check the meter; the town does not have to pull a meter unless there is good reason to think it is inaccurate.', 'Una queja sobre una factura no exime de pagarla a tiempo (Código Municipal § 10-4). Si cree que una lectura está mal, pague la factura y pida a Facturación que revise el medidor; el pueblo no tiene que retirar un medidor salvo que haya buena razón para pensar que está mal.'],
  ex_bl_cut_p3: ['The policy does not describe a payment plan. If you cannot pay in full, call Billing before the 15th and ask what the office can do. [Town Hall to confirm whether payment arrangements are offered.]', 'La política no describe un plan de pagos. Si no puede pagar todo, llame a Facturación antes del 15 y pregunte qué puede hacer la oficina. [La Alcaldía debe confirmar si ofrece arreglos de pago.]'],
  ex_bl_start_h: ['Starting service: deposit and fees', 'Iniciar el servicio: depósito y tarifas'],
  ex_bl_start_p: ['Applications are made at the Treasurer’s office on the town’s form (Town Code § 10-1); the accepted application is your contract with the town. The online form on this site collects the same answers so the visit is short.', 'La solicitud se hace en la oficina del Tesorero con el formulario del pueblo (Código Municipal § 10-1); la solicitud aceptada es su contrato con el pueblo. El formulario en línea de este sitio recoge las mismas respuestas para que la visita sea corta.'],
  ex_bl_deposit: ['Residential deposit', 'Depósito residencial'],
  ex_bl_deposit_v: ['$100.00, paid when you apply', '$100.00, al presentar la solicitud'],
  ex_bl_comm: ['Commercial deposit', 'Depósito comercial'],
  ex_bl_comm_v: ['Set case by case by town staff, usually a multiple of the residential charge based on expected use', 'Lo fija el personal caso por caso, normalmente un múltiplo del cargo residencial según el consumo previsto'],
  ex_bl_fee: ['Turn-on or restoration fee', 'Tarifa de conexión o reconexión'],
  ex_bl_fee_v: ['$35.00, paid before staff turn the water on', '$35.00, antes de que el personal abra el agua'],
  ex_bl_use: ['Start using it within', 'Empiece a usarlo dentro de'],
  ex_bl_use_v: ['30 days of the service being made available, or billing starts anyway unless Council approves a waiver', '30 días desde que el servicio está disponible; si no, la facturación empieza igual salvo que el Concejo apruebe una exención'],
  ex_bl_conn_h: ['Connection fees for a new tap', 'Tarifas de conexión para una toma nueva'],
  ex_bl_conn_p: ['A connection fee pays for making the connection and for part of the plant and lines that serve it. It is due when the written application is filed and accepted by Town Council, and it applies to each connection in a project. Fees have been in effect since July 1, 2019.', 'La tarifa de conexión cubre hacer la conexión y parte de la planta y las líneas que la sirven. Se paga al presentar la solicitud escrita y ser aceptada por el Concejo Municipal, y aplica a cada conexión de un proyecto. Las tarifas rigen desde el 1 de julio de 2019.'],
  ex_bl_conn_cap: ['Town of Keysville connection fees, effective July 1, 2019, by water meter size', 'Tarifas de conexión del Town of Keysville, vigentes desde el 1 de julio de 2019, según el tamaño del medidor'],
  ex_bl_meter: ['Meter size (inches)', 'Medidor (pulgadas)'],
  ex_bl_water_fee: ['Water facility fee', 'Tarifa de agua'],
  ex_bl_sewer_fee: ['Sewer facility fee', 'Tarifa de alcantarillado'],
  ex_bl_total: ['Total', 'Total'],
  ex_bl_rates_h: ['Rates', 'Tarifas'],
  ex_bl_rates_p: ['Council sets rates by ordinance after a public hearing. The table shows the rates proposed for the 2026–2027 fiscal year, as advertised for the July 13, 2026 hearing, next to the rates in effect before it. [Town Hall to confirm the rates Council adopted.]', 'El Concejo fija las tarifas por ordenanza después de una audiencia pública. La tabla muestra las tarifas propuestas para el año fiscal 2026–2027, tal como se anunciaron para la audiencia del 13 de julio de 2026, junto a las tarifas vigentes antes. [La Alcaldía debe confirmar las tarifas que adoptó el Concejo.]'],
  ex_bl_rates_cap: ['Monthly water and sewer rates. Per-gallon amounts are in dollars per gallon.', 'Tarifas mensuales de agua y alcantarillado. Los montos por galón están en dólares por galón.'],
  ex_bl_r_item: ['Charge', 'Cargo'],
  ex_bl_r_before: ['Before July 2026', 'Antes de julio de 2026'],
  ex_bl_r_proposed: ['Proposed 2026–2027', 'Propuesta 2026–2027'],
  ex_bl_r_wi_base: ['Water, in town: base', 'Agua, dentro del pueblo: base'],
