  /* Town taxes, licenses and fees */
  ex_tx_title: ['Town taxes, licenses and fees', 'Impuestos, licencias y tarifas del pueblo'],
  ex_tx_eyebrow: ['What the town charges', 'Lo que cobra el pueblo'],
  ex_tx_lead: ['Keysville levies a few taxes of its own on top of Charlotte County’s. This page lists each one, the rate, who pays it and when, from the town’s budget notices and the Town Code.', 'Keysville cobra algunos impuestos propios además de los del Condado de Charlotte. Esta página enumera cada uno, la tasa, quién lo paga y cuándo, según los avisos de presupuesto del pueblo y el Código Municipal.'],
  ex_tx_prop_h: ['Town property tax', 'Impuesto predial del pueblo'],
  ex_tx_prop_p: ['Property inside town limits is taxed twice: once by Charlotte County and once by the town. The county assesses the value; the town applies its own rate to it. These are the levies advertised for tax year 2026 in the FY 2026–2027 budget notice. [Town Hall to confirm the rates Council adopted, and when town tax bills are mailed and due.]', 'La propiedad dentro de los límites del pueblo paga impuesto dos veces: al Condado de Charlotte y al pueblo. El condado tasa el valor; el pueblo aplica su propia tasa. Estas son las tasas anunciadas para el año fiscal 2026 en el aviso de presupuesto 2026–2027. [La Alcaldía debe confirmar las tasas que adoptó el Concejo y cuándo se envían y vencen las facturas del pueblo.]'],
  ex_tx_prop_cap: ['Town of Keysville tax levies advertised for tax year 2026, per $100 of assessed value', 'Tasas del Town of Keysville anunciadas para el año fiscal 2026, por cada $100 de valor tasado'],
  ex_tx_kind: ['Tax', 'Impuesto'],
  ex_tx_rate: ['Rate', 'Tasa'],
  ex_tx_re: ['Real estate', 'Bienes inmuebles'],
  ex_tx_mh: ['Mobile homes', 'Casas móviles'],
  ex_tx_pp: ['Personal property (vehicles)', 'Propiedad personal (vehículos)'],
  ex_tx_mt: ['Machinery and tools', 'Maquinaria y herramientas'],
  ex_tx_per100: ['per $100', 'por cada $100'],
  ex_tx_history: ['For 2025 the town advertised a real estate rate of $0.12, down from $0.16, after a reassessment raised values. The notice for that hearing is on the Documents page.', 'Para 2025 el pueblo anunció una tasa de bienes inmuebles de $0.12, bajando de $0.16, después de que una retasación subió los valores. El aviso de esa audiencia está en la página de Documentos.'],
  ex_tx_relief_h: ['Tax relief for older and disabled homeowners', 'Alivio fiscal para propietarios mayores o con discapacidad'],
  ex_tx_relief_p: ['Real estate tax relief for homeowners 65 and older or permanently disabled is run by the Charlotte County Commissioner of the Revenue, 205 David Bruce Avenue, Charlotte Court House, 434-542-5546. [Town Hall to confirm whether the town honors the county exemption on its own levy.]', 'El alivio del impuesto inmobiliario para propietarios de 65 años o más o con discapacidad permanente lo administra el Comisionado de Ingresos del Condado de Charlotte, 205 David Bruce Avenue, Charlotte Court House, 434-542-5546. [La Alcaldía debe confirmar si el pueblo aplica la exención del condado a su propio impuesto.]'],
  ex_tx_meals_h: ['Meals tax: 6 percent', 'Impuesto sobre comidas: 6 por ciento'],
  ex_tx_meals_p1: ['Anyone who sells a prepared meal in town collects a 6 percent town tax from the customer (Town Code § 12-2). Prepackaged candy, snacks, bulk food, sealed drinks, school and hospital meals, vending machines and up to three fundraiser meals a year by a nonprofit or church are exempt (§ 12-4).', 'Quien venda una comida preparada en el pueblo cobra al cliente un impuesto municipal del 6 por ciento (Código Municipal § 12-2). Están exentos los dulces y bocadillos empacados, la comida al mayoreo, las bebidas selladas, las comidas de escuelas y hospitales, las máquinas expendedoras y hasta tres comidas de recaudación al año de una organización sin fines de lucro o iglesia (§ 12-4).'],
  ex_tx_meals_p2: ['Sellers report and pay the tax to the Treasurer at least every 30 days, by the 20th of the following month (§ 12-6). Paying on time earns a 1 percent discount (§ 12-7). Paying late adds a 10 percent penalty and 10 percent annual interest (§ 12-8).', 'Los vendedores declaran y pagan el impuesto al Tesorero al menos cada 30 días, antes del día 20 del mes siguiente (§ 12-6). Pagar a tiempo da un descuento del 1 por ciento (§ 12-7). Pagar tarde agrega un recargo del 10 por ciento y un interés anual del 10 por ciento (§ 12-8).'],
  ex_tx_cig_h: ['Cigarette tax', 'Impuesto a los cigarrillos'],
  ex_tx_cig_p: ['The town levies $0.15 on each pack of 20 cigarettes sold in town, paid by the dealer with a town stamp (Town Code § 12-12, effective February 1, 2020).', 'El pueblo cobra $0.15 por cada paquete de 20 cigarrillos vendido en el pueblo, pagado por el distribuidor con un sello municipal (Código Municipal § 12-12, vigente desde el 1 de febrero de 2020).'],
  ex_tx_bpol_h: ['Business license (BPOL)', 'Licencia de negocio (BPOL)'],
  ex_tx_bpol_p: ['Every business in town buys a license each year, due by March 1. The fee is based on the previous calendar year’s gross receipts. Doing business after March 1 without a license adds a 10 percent penalty.', 'Todo negocio del pueblo compra una licencia cada año, con vencimiento el 1 de marzo. La tarifa se basa en los ingresos brutos del año calendario anterior. Operar después del 1 de marzo sin licencia agrega un recargo del 10 por ciento.'],
  ex_tx_bpol_cap: ['Business license fee schedule from the 2026 application', 'Tabla de tarifas de licencia de negocio según la solicitud de 2026'],
  ex_tx_biz_type: ['Type of business', 'Tipo de negocio'],
  ex_tx_fee: ['Fee', 'Tarifa'],
  ex_tx_retail: ['Retail merchant', 'Comercio minorista'],
  ex_tx_wholesale: ['Wholesale merchant', 'Comercio mayorista'],
  ex_tx_service: ['Personal or repair service', 'Servicio personal o de reparación'],
